"""Inspected passages and access limitations, frozen at the research cutoff."""
ASOF='2026-11-16'
sources=[]; retrievals=[]
def src(n,title,author,url,date,kind,locator,passage,note='',status='Passage inspected',origin=None):
    sid=f'S{n:03d}'; origin=origin or author+' | '+title
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'Publication date':date,'URL':url,'Access date':ASOF,'Source class':kind,'Primary or secondary':'Primary' if kind in ['Official record','Statute','Court record','Interested biography'] else 'Secondary','Access status':status,'Origin ID':origin,'Locator':locator,'Reliability / limitation note':note or 'Supports the specified passage; no wider causal inference.','Geographic / language scope':'Telangana / Telugu' if n==34 else 'India / English'})
    retrievals.append({'id':f'R{n:03d}','source_id':sid,'url':url,'access_date':ASOF,'route':'Canonical page or identified reproduction','access_status':status,'origin_id':origin,'locator':locator,'passage_paraphrase':passage,'method':'Web page/PDF passage inspection' if status=='Passage inspected' else 'Indexed extraction; canonical fetch failed','result':status,'next_action':'Reuse for the bounded claim' if status=='Passage inspected' else 'Inspect original before extending support'})

